const D = { density: .5, energy: .6, speed: 1, scale: 1, hue: 210, x: .5, y: .5, style: 'stained', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- drifting point cloud: rebuild base only on seed or count change ----
const N = Math.round(40 + clp(P.density, 0, 1) * 80); // 40..120 interior points
if (S.seedUsed !== P.seed || S.nUsed !== N) {
  S.seedUsed = P.seed; S.nUsed = N;
  S.hoff = fr(5) * 60;
  S.pts = [];
  for (let i = 0; i < N; i++) {
    const a1 = fr(i * 4 + 11), a2 = fr(i * 4 + 12), a3 = fr(i * 4 + 13), a4 = fr(i * 4 + 14);
    S.pts.push({
      hx: -0.1 + a1 * 1.2, hy: -0.1 + a2 * 1.2,        // home in extended domain
      vx: fr(i * 4 + 15) - 0.5, vy: fr(i * 4 + 16) - 0.5, // net drift direction
      f1: a3 * TAU, f2: a4 * TAU, ds: 0.5 + fr(i * 4 + 17) * 1.3
    });
  }
  // fixed border ring guarantees full-frame coverage (outside the wrap band)
  S.bord = [];
  const lo = -0.18, hi = 1.18, st = 4;
  for (let s = 0; s < st; s++) { const f = s / (st - 1); S.bord.push([lo + f * (hi - lo), lo]); S.bord.push([lo + f * (hi - lo), hi]); }
  for (let s = 1; s < st - 1; s++) { const f = s / (st - 1); S.bord.push([lo, lo + f * (hi - lo)]); S.bord.push([hi, lo + f * (hi - lo)]); }
}

const style = P.style;
const tp = K.t * (0.06 + P.speed * 0.16);          // drift clock
const tflow = K.t * (0.10 + P.speed * 0.15);        // gem surface undulation
const amp = 0.018 + clp(P.energy, 0, 1) * 0.05 + A.rms * 0.05;
const netv = 0.02 + clp(P.energy, 0, 1) * 0.05;     // net drift speed
const hb = (P.hue + K.section * 20 + S.hoff) % 360;
const expo = 0.75 + clp(P.energy, 0, 1) * 0.5 + K.intensity * 0.3 + A.bass * 0.4;
const edgeGlow = 0.5 + K.intensity * 0.5 + A.bass * 0.6 + K.pulse * 0.3; // edge brightness driver

// wrap into [-0.12, 1.12), period 1.24
const wr = v => { let x = (v + 0.12) % 1.24; if (x < 0) x += 1.24; return x - 0.12; };

// iq cosine palette (rgb 0..1), rotated by base hue
const pal = m => { const hr = hb / 360; return [
  0.5 + 0.5 * Math.cos(TAU * (m + hr)),
  0.5 + 0.5 * Math.cos(TAU * (m + hr + 0.33)),
  0.5 + 0.5 * Math.cos(TAU * (m + hr + 0.66)) ]; };
function rgb2hsb(r, g, b) { const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn; let h = 0;
  if (d > 1e-6) { if (mx === r) h = ((g - b) / d) % 6; else if (mx === g) h = (b - r) / d + 2; else h = (r - g) / d + 4; h *= 60; if (h < 0) h += 360; }
  return [h, mx <= 0 ? 0 : d / mx * 100, Math.min(1, mx) * 100]; }
function hgt(x, y) { return Math.sin(x * 5.5 + tflow) + Math.cos(y * 4.7 - tflow * 0.8) + 0.6 * Math.sin((x + y) * 3.3 + tflow * 0.5); }

// ---- assemble current point positions ----
const XS = [], YS = [];
for (let i = 0; i < N; i++) {
  const pt = S.pts[i];
  const ox = amp * (Math.sin(tp * pt.ds + pt.f1) + 0.5 * Math.sin(tp * pt.ds * 1.7 + pt.f2)) + pt.vx * netv * tp;
  const oy = amp * (Math.cos(tp * pt.ds * 0.9 + pt.f2) + 0.5 * Math.cos(tp * pt.ds * 1.3 + pt.f1)) + pt.vy * netv * tp;
  XS.push(wr(pt.hx + ox)); YS.push(wr(pt.hy + oy));
}
for (let i = 0; i < S.bord.length; i++) { XS.push(S.bord[i][0]); YS.push(S.bord[i][1]); }
const M = XS.length;
XS.push(-8, 8, 0); YS.push(-8, -8, 8); // super-triangle

// ---- Bowyer-Watson Delaunay (small N, per frame) ----
function circum(ax, ay, bx, by, cx, cy) { const dd = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by));
  if (Math.abs(dd) < 1e-12) return [0, 0, -1];
  const a2 = ax * ax + ay * ay, b2 = bx * bx + by * by, c2 = cx * cx + cy * cy;
  const ux = (a2 * (by - cy) + b2 * (cy - ay) + c2 * (ay - by)) / dd, uy = (a2 * (cx - bx) + b2 * (ax - cx) + c2 * (bx - ax)) / dd;
  return [ux, uy, (ax - ux) * (ax - ux) + (ay - uy) * (ay - uy)]; }
function mk(a, b, c) { return { a: a, b: b, c: c, cc: circum(XS[a], YS[a], XS[b], YS[b], XS[c], YS[c]) }; }
let tris = [mk(M, M + 1, M + 2)];
for (let p = 0; p < M; p++) {
  const pxx = XS[p], pyy = YS[p], edges = [], keep = [];
  for (let ti = 0; ti < tris.length; ti++) { const T = tris[ti], cc = T.cc; let bad = false;
    if (cc[2] >= 0) { const dx = pxx - cc[0], dy = pyy - cc[1]; if (dx * dx + dy * dy < cc[2] - 1e-12) bad = true; }
    if (bad) { edges.push(T.a, T.b, T.b, T.c, T.c, T.a); } else keep.push(T); }
  const ne = edges.length / 2;
  for (let e = 0; e < ne; e++) { const a = edges[2 * e], b = edges[2 * e + 1]; let cnt = 0;
    for (let f = 0; f < ne; f++) { const c2 = edges[2 * f], d2 = edges[2 * f + 1]; if ((a === c2 && b === d2) || (a === d2 && b === c2)) cnt++; }
    if (cnt === 1) keep.push(mk(a, b, p)); }
  tris = keep;
}

// ---- render facets + edges ----
push();
const al = P.alpha;
noStroke();
if (style === 'wireframe') { fill((hb + 210) % 360, 45, 7, al); rect(0, 0, width, height); }
else if (style === 'blueprint') { fill(212, 70, 12, al); rect(0, 0, width, height); }
else if (style === 'ink') { fill(36, 10, 84, al); rect(0, 0, width, height); }
const swBase = Math.max(1, u * 0.0016);
const lx = P.x - 0.5, ly = P.y - 0.5, lz = 0.8, lm = Math.hypot(lx, ly, lz) || 1; // gem light dir
const Lx = lx / lm, Ly = ly / lm, Lz = lz / lm;
let addOn = false;
if (style === 'wireframe') { blendMode(ADD); addOn = true; }

for (let ti = 0; ti < tris.length; ti++) {
  const T = tris[ti];
  if (T.a >= M || T.b >= M || T.c >= M) continue;
  const ax = XS[T.a], ay = YS[T.a], bx = XS[T.b], by = YS[T.b], cx2 = XS[T.c], cy2 = YS[T.c];
  const mx = (ax + bx + cx2) / 3, my = (ay + by + cy2) / 3;   // centroid (fraction coords)
  const msc = mx * 0.55 + my * 0.4 + K.t * 0.012;             // centroid-position color scalar + drift
  const cc = pal(msc), hs = rgb2hsb(cc[0], cc[1], cc[2]);
  const X1 = ax * width, Y1 = ay * height, X2 = bx * width, Y2 = by * height, X3 = cx2 * width, Y3 = cy2 * height;

  if (style === 'wireframe') {
    noStroke(); fill(hs[0], clp(hs[1] * 0.8, 0, 100), 6 + hs[2] * 0.06, al * 0.5);
    triangle(X1, Y1, X2, Y2, X3, Y3);
    noFill(); stroke(hs[0], clp(50 + hs[1] * 0.4, 0, 100), clp(55 * edgeGlow + 30, 0, 100), al * 0.9);
    strokeWeight(swBase * 1.1); triangle(X1, Y1, X2, Y2, X3, Y3);
  } else if (style === 'gem') {
    const ha = hgt(ax, ay), hbv = hgt(bx, by), hc = hgt(cx2, cy2);
    const ux = bx - ax, uy = by - ay, uz = (hbv - ha) * 0.12, vx2 = cx2 - ax, vy2 = cy2 - ay, vz = (hc - ha) * 0.12;
    let nx = uy * vz - uz * vy2, ny = uz * vx2 - ux * vz, nz = ux * vy2 - uy * vx2;
    const nl = Math.hypot(nx, ny, nz) || 1; nx /= nl; ny /= nl; nz /= nl;
    let ndl = nx * Lx + ny * Ly + nz * Lz; if (ndl < 0) ndl = -ndl * 0.4;
    const lit = clp(22 + ndl * 70 * expo, 8, 96), spec = ndl > 0.86 ? (ndl - 0.86) * 260 * expo : 0;
    noStroke(); fill(hs[0], clp(hs[1] * 0.9 + 18, 25, 95), clp(lit + spec, 6, 100), al);
    triangle(X1, Y1, X2, Y2, X3, Y3);
  } else if (style === 'blueprint') {
    const val = 0.5 + 0.5 * Math.cos(TAU * msc);
    noStroke(); fill(212, clp(60 - val * 20, 0, 100), clp(9 + val * 10, 0, 100), al);
    triangle(X1, Y1, X2, Y2, X3, Y3);
    noFill(); stroke(196, 26, clp(70 * edgeGlow + 22, 0, 100), al * 0.92);
    strokeWeight(swBase * 0.9); triangle(X1, Y1, X2, Y2, X3, Y3);
  } else if (style === 'ink') {
    const val = 0.5 + 0.5 * Math.cos(TAU * msc), paper = clp(88 - val * 46, 20, 92);
    noStroke(); fill(34, clp(10 + val * 8, 0, 40), paper, al);
    triangle(X1, Y1, X2, Y2, X3, Y3);
    noFill(); stroke(28, 22, clp(26 - val * 10, 8, 40), al * 0.85);
    strokeWeight(swBase * (0.8 + val * 0.9)); triangle(X1, Y1, X2, Y2, X3, Y3);
  } else { // stained-poly (default): centroid-hue jewel fill + BRIGHT edges (the living web)
    const fillB = clp(38 + hs[2] * 0.45 * expo, 14, 82);
    noStroke(); fill(hs[0], clp(hs[1] * 0.95 + 18, 30, 96), fillB, al);
    triangle(X1, Y1, X2, Y2, X3, Y3);
    noFill(); stroke((hs[0] + 8) % 360, clp(hs[1] * 0.5 + 10, 0, 70), clp(70 * edgeGlow + 26, 0, 100), al * 0.95);
    strokeWeight(swBase * 1.15); triangle(X1, Y1, X2, Y2, X3, Y3);
  }
}
if (addOn) blendMode(BLEND);
pop();

// ---- audio sparkle on vertices (treble) — partial, never full-frame strobe ----
if ((A.treble > 0.02 || A.rms > 0.02) && al > 5) {
  push(); blendMode(ADD); noStroke();
  const spk = (A.treble * 0.7 + A.rms * 0.3) * clp(P.energy, 0, 1), hh = (hb + 40) % 360;
  const nn = Math.min(N, 40);
  for (let i = 0; i < nn; i++) { fill(hh, 30, 100, spk * 38 * (al / 100)); circle(XS[i] * width, YS[i] * height, u * 0.02 * (1 + spk)); }
  blendMode(BLEND); pop();
}
blendMode(BLEND);
